# bash completion for tando. Generated by completions/gen.sh: edit that, not this file.
# COMPREPLY=($(compgen ...)) is the bash 3.2 idiom (mapfile is bash 4); words are single tokens.
# shellcheck disable=SC2207,SC2046
# bash 3.2 compatible. Install: source it from ~/.bashrc, or copy it to
# $(brew --prefix)/etc/bash_completion.d/tando (install.sh puts it in
# PREFIX/share/bash-completion/completions/tando).

_tando_cfg() { printf '%s' "${TANDO_CONFIG_DIR:-$HOME/.config/tando}"; }
_tando_hosts() {
  local f
  for f in "$(_tando_cfg)"/hosts/*; do [ -f "$f" ] && printf '%s\n' "${f##*/}"; done
}
_tando_apps() {
  local f
  [ -f tando.conf ] && sed -n 's/^[[:space:]]*app[[:space:]]*=[[:space:]]*\([a-z0-9-]*\).*/\1/p' tando.conf
  for f in "$(_tando_cfg)"/cache/apps.*; do [ -f "$f" ] && cat "$f"; done
  return 0
}
_tando_plugins() { # plugin commands next to the tando on PATH
  local self d f
  self=$(command -v tando 2> /dev/null) || return 0
  while [ -L "$self" ]; do
    d=$(readlink "$self")
    case $d in /*) self=$d;; *) self=$(dirname "$self")/$d;; esac
  done
  for f in "$(dirname "$self")"/../lib/cmd-*.sh; do
    [ -f "$f" ] || continue
    f=${f##*/cmd-}; printf '%s\n' "${f%.sh}"
  done
}
_tando_commands="init up deploy rollback releases history status ls logs start stop restart top env jobs db 
  backup restore host domain doctor version destroy unlock recipes ci alerts health errors 
  requests audit adopt help cheat go link next open ssh"

_tando() {
  local cur prev cmd w i
  cur=${COMP_WORDS[COMP_CWORD]}
  prev=${COMP_WORDS[COMP_CWORD-1]}
  COMPREPLY=()
  case $prev in
    -a) COMPREPLY=($(compgen -W "$(_tando_apps)" -- "$cur")); return 0;;
    -H) COMPREPLY=($(compgen -W "$(_tando_hosts)" -- "$cur")); return 0;;
    -n|--watch|--port) return 0;;
    --key) COMPREPLY=($(compgen -f -- "$cur")); return 0;;
  esac
  # the command is the first word that is not an option or an option's value
  cmd="" i=1
  while [ "$i" -lt "$COMP_CWORD" ]; do
    w=${COMP_WORDS[i]}
    case $w in -a|-H|-n|--watch) i=$((i + 2)); continue;; -*) ;; *) cmd=$w; break;; esac
    i=$((i + 1))
  done
  if [ -z "$cmd" ]; then
    case $cur in
      -*) COMPREPLY=($(compgen -W "-a -H -h --help" -- "$cur"));;
      *) # shellcheck disable=SC2086 # the command list is split into words on purpose
        COMPREPLY=($(compgen -W "$(printf '%s\n' $_tando_commands $(_tando_plugins) | sort -u)" -- "$cur"));;
    esac
    return 0
  fi
  local subs="" flags="" args="" sub=${COMP_WORDS[i+1]:-}
  case $cmd in
    init) subs="" flags="$flags -H --yes" args="";;
    up) subs="" flags="$flags -H --yes --force --wait" args="";;
    deploy) subs="" flags="$flags -a -H --force --yes --wait --dry-run" args="";;
    rollback) subs="" flags="$flags -H -a" args="apps";;
    releases) subs="" flags="$flags -H --json -a" args="apps";;
    history) subs="" flags="$flags -n -H --json -a" args="apps";;
    status) subs="" flags="$flags --watch -H --json -a" args="apps";;
    ls) subs="" flags="$flags -H --all --watch --json" args="";;
    logs) subs="pull" flags="$flags -f -n --since --until --grep -i --regex -E -a -H --level --release --deploy --json" args="apps";;
    start) subs="" flags="$flags -H -a" args="apps";;
    stop) subs="" flags="$flags -H -a" args="apps";;
    restart) subs="" flags="$flags -H -a" args="apps";;
    top) subs="" flags="$flags --watch --read-only -H" args="hosts";;
    env) subs="ls set unset import" flags="$flags --show -a -H" args="apps";;
    jobs) subs="run ls" flags="$flags -H -a" args="apps";;
    db) subs="psql url studio info" flags="$flags -a -H --show --no-open --idle --stop" args="apps";;
    backup) subs="ls now restore pull offsite" flags="$flags -a -H --yes --show --saved --import --rotate" args="apps";;
    restore) subs="" flags="$flags -a --yes -H --from-host --all" args="";;
    host) subs="add setup ls rm status care update reboot" flags="$flags --port --key --yes --force --insecure-test --no-check --deploy --json --watch --all --now --updates --reboot --window --tz --lead --even-with-other-sites" args=""
      [ "$COMP_CWORD" -eq $((i + 2)) ] && case $sub in setup|rm) args=hosts;; esac;;
    domain) subs="add rm ls" flags="$flags --www --wait --force -a -H" args="apps";;
    doctor) subs="" flags="$flags -H" args="hosts";;
    version) subs="" flags="$flags -H" args="";;
    destroy) subs="" flags="$flags -H --purge --yes -a" args="apps";;
    unlock) subs="" flags="$flags -H -a" args="apps";;
    recipes) subs="" flags="$flags " args="";;
    ci) subs="setup rotate ls revoke github hook" flags="$flags -a -H --ref --repo --branch --node --env --force --remove" args="";;
    alerts) subs="enable disable test history set silence notifier rm ls heartbeat backup-ping show notifiers" flags="$flags --watch -n -a -H" args="apps";;
    health) subs="" flags="$flags --json -a -H --forget" args="apps";;
    errors) subs="" flags="$flags --since -n --json -a -H --last" args="apps";;
    requests) subs="tail errors summary" flags="$flags --since -a -H --last -n -f --4xx" args="apps";;
    audit) subs="" flags="$flags -n -H -a" args="apps";;
    adopt) subs="plan apply undo status site" flags="$flags --health --no-jobs --yes --accept-502 -H --apply" args="apps";;
    help) subs="" flags="$flags " args="";;
    cheat) subs="" flags="$flags " args="";;
    go) subs="" flags="$flags --port --key --domain --dns --yes --forget" args="";;
    link) subs="" flags="$flags " args="apps";;
    next) subs="" flags="$flags -H" args="apps";;
    open) subs="" flags="$flags " args="apps";;
    ssh) subs="" flags="$flags " args="apps";;
  esac
  case $cur in -*) COMPREPLY=($(compgen -W "$flags" -- "$cur")); return 0;; esac
  if [ -n "$subs" ] && [ "$COMP_CWORD" -eq $((i + 1)) ]; then
    COMPREPLY=($(compgen -W "$subs" -- "$cur"))
  elif [ "$args" = hosts ]; then COMPREPLY=($(compgen -W "$(_tando_hosts)" -- "$cur"))
  elif [ "$args" = apps ]; then COMPREPLY=($(compgen -W "$(_tando_apps)" -- "$cur"))
  fi
  return 0
}
complete -F _tando tando
